sources.Equality.ets:
export class Equality {
 count: number = 0;
 check(): boolean { return this.count === 2; }
}

sources.Loose.ets:
export class Loose {
 count: number = 0;
 test(): void { this.count==2; }
}

sources.Assign.ets:
export class Assign {
 count: number = 0;
 test(): void { this.count=2; }
}

sources.Add.ets:
export class Add {
 count: number = 0;
 test(): void { this.count+=2; }
}

sources.Subtract.ets:
export class Subtract {
 count: number = 0;
 test(): void { this.count-=2; }
}

sources.Increment.ets:
export class Increment {
 count: number = 0;
 test(): void { this.count++; }
}

sources.Decrement.ets:
export class Decrement {
 count: number = 0;
 test(): void { this.count--; }
}

sources.NotEqual.ets:
export class NotEqual {
 count: number = 0;
 test(): void { this.count!=2; }
}

sources.StrictNotEqual.ets:
export class StrictNotEqual {
 count: number = 0;
 test(): void { this.count!==2; }
}

sources.Less.ets:
export class Less {
 count: number = 0;
 test(): void { this.count<=2; }
}

sources.Greater.ets:
export class Greater {
 count: number = 0;
 test(): void { this.count>=2; }
}

sources.ArrowValue.ets:
export class ArrowValue {
 callback: () => void;
 set(): void { this.callback = () => run(); }
}

sources.Mixed.ets:
export class Mixed {
 count: number = 0;
 set(): void { if(this.count===2){this.count=3;} }
}

sources.OnlyText.ets:
export class OnlyText {
 text(): string { return `SymbolGlyph('arrow').rotate({ angle: this.expanded ? 0 : 180 }); this.expanded = !this.expanded;`; }
}
